import{payAt,payStatus,comfortableTarget,comparisonPair,collegeLane}from'./developer/results-board-080-model.js';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number.isFinite(n)?'$'+Math.round(n/1000).toLocaleString()+'k':'Not estimated';
const annual=n=>Number.isFinite(n)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n):'Not estimated';
const concepts={a:{title:'The quiet shortlist',copy:'A few clear choices, then detail when you want it.',recommend:true},b:{title:'The lifestyle map',copy:'See the money tradeoffs before opening a career.'},c:{title:'The comparison desk',copy:'Start with two routes, and work toward a choice.'}};
const app=document.getElementById('mockapp'),control=document.getElementById('prototype-controls'),dialog=document.getElementById('detail-dialog');
let data,state,profile,saved=new Set(),toastTimer;
const find=id=>[...profile.supported,...profile.candidates].find(o=>o.id===id),fieldName=id=>data.fields.find(f=>f.id===id)?.title||'Other interests';
const degree=o=>o?.routes.some(r=>['college','graduate'].includes(r.key)),routeName=o=>!o?'Choose a route':o.routes.some(r=>r.key==='college')&&o.routes.some(r=>r.key==='program')?'Associate or bachelor route':o.routeGroup==='graduate'?'Graduate / professional degree':o.routeGroup==='college'?'Bachelor’s degree':o.routeGroup==='program'?(o.routes.find(r=>r.key==='program')?.label||'Certificate / technical training'):o.routeGroup==='apprenticeship'?'Paid apprenticeship':'No college degree';
const income=(o,stage=state.stage)=>payAt(o,stage);
const status=(o,stage=state.stage)=>payStatus(o,stage,profile.lifestyle,state.target);
const badge=(o,stage=state.stage)=>{const s=status(o,stage);const n=income(o,stage),delta=Number.isFinite(n)&&!o.requiresExperience?n-state.target:null;return `<span class="status ${s.key}"><strong>${s.key==='unknown'?'PAY UNKNOWN':delta>=0?'MEETS TARGET':'BELOW TARGET'}</strong>${delta===null?'':`<span>${money(Math.abs(delta))} / year ${delta>=0?'above':'short'}</span>`}</span>`;};
const stageLabel=()=>state.stage==='year5'?'5-year planning scenario':'First qualified role';
function loadSaved(){saved=new Set(data.saved||[]);}
function defaultPair(){state.pair=comparisonPair(comparisonOffers085());}
function setProfile(id){profile=data.profiles.find(p=>p.id===id)||data.profiles[0];Object.assign(state,{profile:profile.id,target:profile.lifestyle.target,field:'all',query:'',route:'all',minimum:'',coversOnly:false,topOnly:false,includeCandidates:true,allChart:false,exploreLimit:12});defaultPair();loadSaved();}
function notify(text){const n=document.getElementById('toast');n.textContent=text;n.className='toast';clearTimeout(toastTimer);toastTimer=setTimeout(()=>{n.textContent='';n.className='';},2800);}
function showDialog(title,body){document.getElementById('dialog-content').innerHTML=`<div class="dialog-body"><div class="dialog-head"><h2 id="dialog-title">${h(title)}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div>${body}</div>`;if(!dialog.open)dialog.showModal();parent.postMessage({type:'fieldguide-board-dialog'},location.origin);}
function sources(o){return `<details><summary>Pay sources & assumptions</summary><p>First qualified-role figure: ${annual(o.entry)}. Five-year scenario: ${annual(o.year5)}.</p><p>${h(o.entryBasis)} · ${h(o.geography)} · ${h(o.period)}.</p><p>Five years starts after required education, credentials and preparation. It does not mean five years from today. Tuition, aid, study time and any loan payments not already entered need a separate comparison.</p>${o.paySources.filter(s=>s.url).map(s=>`<p><a href="${h(s.url)}" target="_blank" rel="noopener">${h(s.publisher)} · ${h(s.title)} ↗</a></p>`).join('')}${o.payNotes.map(n=>`<p>${h(n)}</p>`).join('')}</details>`;}
function careerDetail(id){const o=find(id);if(!o)return;showDialog(o.title,`<span class="tag ${o.candidate?'possible':o.top?'top':''}">${o.candidate?(o.mixedInterests?'Mixed interests · review your answers':'Exploration · needs confirmation'):o.top?'Supported Top match':'Supported option'}</span><p>${h(o.fields.map(fieldName).join(' · '))}</p><div class="pathway-values"><div><span>First qualified role · annual gross</span><strong>${money(o.entry)}</strong></div><div><span>After 5 years · planning scenario</span><strong class="${o.year5===null?'unestimated':''}">${money(o.year5)}</strong></div></div><p>${badge(o,'entry')}</p>${o.candidate?'<p>This is an unconfirmed exploration candidate. It has not earned a supported match label.</p>':''}${o.broadDisagreement?'<p>Your direct activity evidence and broader interest pattern point in different directions. This option deserves a closer look before you commit.</p>':''}<h3>${data.modelView?"Recorded profile interests":"Why this matches"}</h3><p>Your recorded interest evidence.</p><ul>${o.knownEvidence.map(e=>`<li>${h(e)}</li>`).join('')||'<li>More direct evidence is needed.</li>'}</ul>${o.variableHours?'<p>This work often has variable hours. The annual pay example does not guarantee full-time or year-round work.</p>':''}<h3>A route to explore</h3><p>${h(routeName(o))}. ${h(o.preparation.join(' · '))}</p>${o.routes.length>1?'<p>'+o.routes.map(r=>h(r.label)+(r.detail?' · '+h(r.detail):'')).join('<br/>')+'</p>':''}${o.training?`<p><strong>Paid preparation comes first:</strong> ${h(o.training.label)} · ${annual(o.training.amount)} / year in the existing example. Qualified-role pay is a later stage.</p>`:''}<div class="card-actions"><button class="primary-button" data-action="open-career" data-id="${h(o.id)}">Full career & plan →</button><button class="primary-button" data-action="save" data-id="${h(o.id)}">${saved.has(o.id)?'Remove from saved':'Save this option'}</button><button class="secondary-button" data-action="experience" data-id="${h(o.id)}">Try a small next step</button></div>${sources(o)}`);}
function intro(title,copy){return `<section class="results-intro"><div><p class="eyebrow">Your results · ${h(profile.firstName)}</p><h1>${title}</h1><p class="intro-copy">${copy}</p></div><div class="lifestyle-card"><span>Needed for selected lifestyle (target)</span><strong>${money(state.target)}<small> / year</small></strong><button class="text-button" data-action="lifestyle">Edit lifestyle</button></div></section>`;}
function fieldChips(){const options=allOptions(),fields=[...new Set(options.flatMap(o=>o.fields))];if(!fields.length)return'';return `<div class="field-chips"><button class="field-chip" data-action="field" data-value="all" aria-pressed="${state.field==='all'}">All fields</button>${fields.map(id=>`<button class="field-chip" data-action="field" data-value="${h(id)}" aria-pressed="${state.field===id}">${h(fieldName(id))} <small>· ${options.filter(o=>o.fields.includes(id)).length}</small></button>`).join('')}</div>`;}
function card(o){return `<article class="career-card ${o.candidate?'candidate-card':''}"><div class="card-top"><span class="tag ${o.candidate?'possible':'top'}">${o.candidate?(o.mixedInterests?'Mixed interests':'Explore'):'Top match'} · ${h(fieldName(o.fields[0]))}</span><button class="save" data-action="save" data-id="${h(o.id)}" aria-label="${saved.has(o.id)?'Unsave':'Save'} ${h(o.title)}" aria-pressed="${saved.has(o.id)}">${saved.has(o.id)?'★':'☆'}</button></div><h3>${h(o.title)}</h3><p class="route-copy">${h(routeName(o))}</p><div class="card-pay">${money(o.entry)} <small>/ year</small></div><p class="salary-caption">Estimate · first qualified role · before tax</p>${badge(o,'entry')}<div class="card-actions"><button class="primary-button" data-action="career" data-id="${h(o.id)}">Explore <span>↗</span></button><label class="compare-check"><input type="checkbox" data-compare="${h(o.id)}" ${state.pair.includes(o.id)?'checked':''}>Compare</label></div></article>`;}
function emptyTop(){return `<div class="empty"><h3>There is more to uncover.</h3><p>Your answers have not established a supported Top yet. You can explore an activity or answer a focused question without choosing a career.</p><button class="primary-button" data-action="next-question">Explore one interest →</button> <button class="secondary-button" data-action="possibilities">See possibilities that need confirmation</button></div>`;}
function tops(){const all=profile.supported.filter(o=>o.top),shown=all.filter(o=>state.field==='all'||o.fields.includes(state.field));return `<section id="start">${profile.profileComplete===false?`<p class="scope-note">Interest profile: ${profile.profileAnswered} of 60 answered. <button class="text-button" data-action="continue-profile">Continue profiling →</button></p>`:''}${data.scopeTitle?`<p class="scope-note">Showing ${h(data.scopeTitle)} <button class="text-button" data-action="all-fields">All my fields →</button></p>`:''}<div class="section-head"><div><h2>${all.length?'Your Top matches':'Your career options'}</h2><p>${profile.supported.length} supported · ${profile.candidates.length} to explore</p></div><a class="text-button" href="#explore">See all options ↓</a></div>${fieldChips()}${shown.length?`<div class="top-grid">${shown.map(card).join('')}</div>`:all.length?'<p>No Top in this field. All options are in the table below.</p>':''}${!shown.length&&!comparisonOffers085().length?emptyTop():''}</section>`;}
function plot(){let rows=allOptions().filter(o=>state.field==='all'||o.fields.includes(state.field));rows=state.allChart?rows:rows.slice(0,6);const values=rows.map(o=>income(o)).filter(Number.isFinite),max=Math.max(50000,Math.ceil(Math.max(state.target*1.25,comfortableTarget(profile.lifestyle,state.target),...values)*1.08/25000)*25000),goal=Math.min(95,state.target/max*100),comfortable=Math.min(100,comfortableTarget(profile.lifestyle,state.target)/max*100),background=`linear-gradient(90deg,#efb2a9 0%,#efb2a9 ${goal}%,#f4d16b ${goal}%,#f4d16b ${comfortable}%,#8fcbaa ${comfortable}%,#8fcbaa 100%)`;
return `<div class="plot-panel"><div class="plot-head"><div><h3>How does the pay fit your life?</h3><p>Annual income before tax · ${h(stageLabel().toLowerCase())}</p></div><div class="segmented" aria-label="Pay stage"><button data-action="stage" data-value="entry" aria-pressed="${state.stage==='entry'}">First role</button><button data-action="stage" data-value="year5" aria-pressed="${state.stage==='year5'}">After 5 years</button></div></div><div class="plot-legend"><span><i style="background:#bc3d32"></i>Below target</span><span><i style="background:#ba7900"></i>Target met</span><span><i style="background:#187947"></i>Room beyond target</span></div>${rows.length?`<div class="plot-axis">${[0,.25,.5,.75,1].map(x=>`<span style="left:${x*100}%">${money(x*max)}</span>`).join('')}<span class="target-label" style="left:${goal}%">Your target ${money(state.target)}</span></div>${rows.map(o=>{const n=income(o),pct=Number.isFinite(n)?Math.max(2,Math.min(94,n/max*100)):0,s=status(o);return `<button class="pay-row" data-action="career" data-id="${h(o.id)}" aria-label="${h(o.title)}: ${money(n)}, ${h(s.text)}"><span class="row-name">${h(o.title)}<span class="match-chip ${o.top?'top':'other'}" aria-label="${o.candidate?'Exploration option, needs confirmation':o.top?'Top match':'Other supported match'}">${o.candidate?'Explore':o.top?'★ Top':'Other'}</span></span><span class="pay-track" style="--goal:${goal}%;--pay:${pct}%;background:${background}">${Number.isFinite(n)?`<i class="pay-line"></i><i class="pay-dot ${s.key}" style="${s.key==='unknown'?'background:#999;box-shadow:0 0 0 1px #999':''}"></i><span class="pay-amount">${money(n)}</span>`:'<span class="muted" style="position:absolute;left:8px;top:9px;font-size:10px">Not estimated</span>'}</span></button>`;}).join('')}`:'<div class="empty"><p>No supported matches to plot yet. Unconfirmed possibilities are kept separate.</p></div>'}<p class="plot-foot">Below target is a money tradeoff, not a poor-interest match. ${state.stage==='year5'?'Five-year figures are planning scenarios after qualification, not guaranteed raises.':'Training or study can come before this qualified-role pay.'} <button class="text-button" data-action="method">How we compare</button></p>${allOptions().length>6?`<button class="text-button" data-action="all-chart">${state.allChart?'Show fewer options':'See all options in the chart'}</button>`:''}</div>`;}
function allOptions(){return [...profile.supported,...(state.includeCandidates?profile.candidates:[])];}
function filtered(){let os=allOptions().filter(o=>(!state.query||(o.title+' '+o.fields.map(fieldName).join(' ')).toLowerCase().includes(state.query.toLowerCase()))&&(state.field==='all'||o.fields.includes(state.field))&&(state.route==='all'||(state.route==='degree'?degree(o):o.routes.some(r=>r.key===state.route)))&&(!state.topOnly||o.top)&&(!state.coversOnly||['good','tight'].includes(status(o).key))&&(!state.minimum||Number.isFinite(income(o))&&income(o)>=Number(state.minimum)*1000));if(state.sort==='match')os.sort((a,b)=>(Number.isFinite(b.correlation)?b.correlation:-2)-(Number.isFinite(a.correlation)?a.correlation:-2));if(state.sort==='pay')os.sort((a,b)=>(income(b)??-1)-(income(a)??-1));return os;}
function explore(){const os=filtered(),groups=new Map();for(const o of os){const field=state.field==='all'?o.fields[0]:state.field;groups.set(field,[...(groups.get(field)||[]),o]);}return `<section class="section-block" id="explore"><div class="section-head"><div><h2>More careers to explore</h2><p>Top, supported and exploration options · sorted within fields</p></div><button class="text-button" data-action="reset">Reset filters</button></div><div class="explore-controls"><label class="search-box"><span aria-hidden="true">⌕</span><input id="career-search" type="search" placeholder="Search a career or field" aria-label="Search recommendations" value="${h(state.query)}"></label><select id="route-filter" aria-label="Education route">${[['all','All education routes'],['degree','Bachelor / graduate'],['college','Bachelor route'],['graduate','Graduate route'],['program','Associate / certificate'],['apprenticeship','Apprenticeship'],['work','No degree · workplace learning']].map(([key,label])=>`<option value="${key}" ${state.route===key?'selected':''}>${label}</option>`).join('')}</select><select id="sort-filter" aria-label="Sort recommendations"><option value="match" ${state.sort==='match'?'selected':''}>Strongest interest fit</option><option value="evidence" ${state.sort==='evidence'?'selected':''}>Supported first</option><option value="pay" ${state.sort==='pay'?'selected':''}>Highest estimated pay</option></select></div><div class="filter-line"><label><input id="budget-only" type="checkbox" ${state.coversOnly?'checked':''}>Meets lifestyle target</label><label><input id="top-only" type="checkbox" ${state.topOnly?'checked':''}>Top matches only</label><label>At least $<input id="minimum-pay" class="minpay" type="number" min="0" max="1000" step="5" value="${h(state.minimum)}" aria-label="Minimum annual pay in thousands">k / year</label><label><input id="include-possibilities" type="checkbox" ${state.includeCandidates?'checked':''}>Include exploration options</label></div><div class="table-caption"><span role="status">${os.length} ${os.length===1?'career':'careers'} · all results shown</span><span>Estimated annual pay · ${h(stageLabel())}</span><span class="table-scroll-hint">More columns →</span></div>${os.length?`<div class="career-table-scroll" role="region" aria-label="All career recommendations, grouped by field" tabindex="0"><table class="career-options-table"><caption class="sr-only">All filtered recommendations. Explore means profession-specific confirmation is still needed.</caption><colgroup><col class="career-col"><col class="match-col"><col class="score-col"><col class="education-col"><col class="pay-col"><col class="fit-col"><col class="save-col"></colgroup><thead><tr><th scope="col">Career</th><th scope="col">Match</th><th scope="col">Interest fit</th><th scope="col">Education</th><th scope="col" class="table-pay">Pay / year</th><th scope="col">Lifestyle fit</th><th scope="col">Save</th></tr></thead>${[...groups].map(([field,items])=>`<tbody aria-label="${h(fieldName(field))}"><tr class="table-field-heading"><th scope="rowgroup" colspan="7">${h(fieldName(field))}<span>${items.length}</span></th></tr>${items.map(o=>`<tr class="career-option-row" data-career-id="${h(o.id)}"><th scope="row"><button class="table-career-link" data-action="career" data-id="${h(o.id)}">${h(o.title)}</button></th><td><button data-action="match-reason" data-id="${h(o.id)}" class="match-chip ${o.candidate?(o.mixedInterests?'mixed':'explore'):o.top?'top':'supported'}" title="${o.candidate?(o.mixedInterests?'Conflicting interests need review':'Exploration option; needs profession-specific confirmation'):o.top?'Supported Top match':'Supported alternative'}">${matchLabel085(o)} ⓘ</button></td><td class="table-score">${score086(o)}</td><td>${h(routeName(o))}</td><td class="table-pay">${money(income(o))}</td><td><span class="table-fit ${status(o).key}">${tableFit085(o)}</span></td><td><button class="save" data-action="save" data-id="${h(o.id)}" aria-label="${saved.has(o.id)?'Unsave':'Save'} ${h(o.title)}" aria-pressed="${saved.has(o.id)}">${saved.has(o.id)?'★':'☆'}</button></td></tr>`).join('')}</tbody>`).join('')}</table></div>`:'<div class="empty"><h3>No options fit these filters.</h3><button class="secondary-button" data-action="reset">Clear filters</button></div>'}<p class="table-key">Interest fit describes broad similarity. Click a match label for evidence. <span class="match-chip explore">Explore</span> Needs confirmation. <span class="match-chip mixed">Mixed</span> Review conflicting interests.</p></section>`;}
function roleSelect(slot){const os=comparisonOffers085().filter(o=>collegeLane(o)===(slot===0)),groups=new Map();for(const o of os){const field=o.fields[0];groups.set(field,[...(groups.get(field)||[]),o]);}return `<select data-pair-slot="${slot}" aria-label="Choose ${slot===0?'college':'no college degree'} profession to compare" ${os.length?'':'disabled'}>${os.length?[...groups].map(([field,items])=>`<optgroup label="${h(fieldName(field))}">${items.map(o=>`<option value="${h(o.id)}" ${state.pair[slot]===o.id?'selected':''}>${h(o.title)} · ${matchLabel085(o)}</option>`).join('')}</optgroup>`).join(''):'<option>No option in this route</option>'}</select>`;}
function compare(){const os=[find(state.pair[0]),find(state.pair[1])],max=Math.max(state.target,...os.map(o=>o?.year5||0))*1.15,diff=os.every(o=>Number.isFinite(o?.year5))?os[0].year5-os[1].year5:null;return `<section class="compare-section" id="compare"><div class="compare-intro"><h2>College vs. no college degree</h2><button class="text-button" data-action="timeline">How pay is estimated</button></div><div class="target-banner">Lifestyle target <strong>${money(state.target)} / year</strong></div><div class="compare-grid">${os.map((o,i)=>`<article class="pathway"><h3>${i===0?'College degree':'No college degree'}</h3>${roleSelect(i)}${o?`<p class="comparison-match"><span class="match-chip ${o.candidate?(o.mixedInterests?'mixed':'explore'):o.top?'top':'supported'}">${matchLabel085(o)}</span>${o.candidate?' <span>Needs confirmation</span>':''}</p><p class="route-copy">${h(routeName(o))}</p><div class="pathway-values"><div><span>First role</span><strong>${money(o.entry)}</strong></div><div><span>After 5 years*</span><strong class="${o.year5===null?'unestimated':''}">${money(o.year5)}</strong></div></div><div class="comparison-bar" aria-label="Five-year pay versus lifestyle target"><div style="width:${Math.max(0,(o.year5||0)/max*100)}%"></div><span style="left:${state.target/max*100}%" title="Lifestyle target"></span></div>${badge(o,'year5')}<div class="card-actions"><button class="text-button" data-action="career" data-id="${h(o.id)}">Explore career ↗</button></div>`:'<p>No option in this route yet.</p>'}</article>`).join('')}</div>${diff!==null?`<div class="pay-difference"><strong>${money(Math.abs(diff))} / year ${diff===0?'difference': 'more'}</strong><span>${diff===0?'Same five-year estimate':h(os[diff>0?0:1].title)+' · at 5 years*'}</span></div>`:''}<p class="estimate-note">*After qualification · estimated annual pay before tax</p></section>`;}

function next(){return `<section class="next-step"><button class="primary-button" data-action="saved">My saved options →</button></section><footer class="results-footer"><span>Pay estimates</span><button class="text-button" data-action="method">Sources & assumptions</button></footer>`;}

function dock(){return state.pair.filter(Boolean).length?`<div class="shortlist-dock"><span><strong>${state.pair.filter(Boolean).length} options on your comparison board</strong><br/>${state.pair.filter(Boolean).map(id=>h(find(id)?.title||'')).join(' · ')}</span><button data-action="jump-compare">Compare routes →</button></div>`:'';}
function render(){control.innerHTML=`<header class="prototype-bar"><div><b>FIELDGUIDE / RESULTS LAB</b><small>Design preview · fictional profiles · research 0.79 · live flow unchanged</small></div><a href="../developer.html" style="font-size:11px;color:#b8c8be">← Developer</a><label><span class="hide">Demo profile</span><select id="demo-profile" aria-label="Choose fictional demonstration profile">${data.profiles.map(p=>`<option value="${h(p.id)}" ${p.id===profile.id?'selected':''}>${h(p.firstName)} · ${h(p.demoLabel)}</option>`).join('')}</select></label></header><nav class="prototype-tabs" aria-label="Alternative results concepts">${Object.entries(concepts).map(([key,c])=>`<button class="concept-tab" data-action="concept" data-value="${key}" aria-pressed="${state.concept===key}"><span class="concept-number">${key.toUpperCase()}</span><span><strong>${c.title}</strong><small>${h(c.copy)}</small></span></button>`).join('')}<button class="ideas-button" data-action="ideas">Ideas worth adding ↗</button></nav><p class="concept-note">${concepts[state.concept].recommend?'<span class="recommend">RECOMMENDED START</span>':''}<span>${state.concept==='a'?'The first screen answers three questions: what fits, what it pays, and whether it fits my life. Everything else opens when needed.':state.concept==='b'?'The financial picture leads. Interest matches stay visible even when their pay is below the lifestyle target.':'A focused workspace for the student who already wants to compare a couple of directions.'}</span></p>`;
const header=`<header class="student-header"><a class="wordmark" href="#start"><span class="brand-icon" aria-hidden="true">↗</span>Fieldguide</a><nav class="student-nav"><a href="#start">Your results</a><a href="#explore">Explore options</a><a href="#compare">Compare routes</a></nav><button class="saved-button" data-action="saved">Saved <strong>${saved.size}</strong></button></header>`;
let body;if(state.concept==='a')body=intro('A few good places to start.','Your matches, pay and lifestyle fit.')+tops()+`<section class="section-block">${plot()}</section>`+explore()+`<section class="section-block">${compare()}</section>`+next();
else if(state.concept==='b')body=intro('Find your balance.','Compare interest fit and income.')+`<section id="start">${fieldChips()}<div class="map-layout">${plot()}<aside class="map-side"><div><p class="eyebrow">Your starting points</p><h2>Fit comes first.</h2></div>${profile.supported.filter(o=>o.top).map(o=>`<div class="side-role"><button data-action="career" data-id="${h(o.id)}">${h(o.title)} ↗</button><strong>${money(income(o))}<small style="font-size:10px;font-weight:400"> / year</small></strong>${badge(o)}</div>`).join('')||'<p>No confirmed Top yet. Try one interest before choosing a direction.</p><button class="secondary-button" data-action="next-question">Explore one interest →</button>'}</aside></div></section>`+explore()+`<section class="section-block">${compare()}</section>`+next();
else body=intro('Make a shortlist you believe in.','Compare careers and routes.')+`<section class="workspace-top" id="start"><aside class="workspace-side"><p class="eyebrow">Your strongest matches</p><h2>Start with what fits.</h2><div class="mini-list">${profile.supported.filter(o=>o.top).map(o=>`<div class="mini-role"><button data-action="career" data-id="${h(o.id)}">${h(o.title)}</button><small>${money(o.entry)} · ${h(routeName(o))}</small><label class="compare-check"><input type="checkbox" data-compare="${h(o.id)}" ${state.pair.includes(o.id)?'checked':''}>On my board</label></div>`).join('')||'<p>No supported Top yet. Explore one interest without committing to a career.</p><button class="primary-button" data-action="next-question">Start with an activity →</button>'}</div></aside>${compare()}</section>`+`<section class="section-block">${plot()}</section>`+explore()+next();
app.innerHTML=`<div class="mock-frame concept-${state.concept} ${data.modelView?'model-view':''}"><main class="student-body">${body}${dock()}</main></div>`;
control.innerHTML='';
}
function renderPreservingFocus(id){const el=document.getElementById(id),position=el?.selectionStart;render();const next=document.getElementById(id);next?.focus({preventScroll:true});if(next&&typeof position==='number'&&next.type==='search')next.setSelectionRange(position,position);}
function ideas(){showDialog('What I would add to the decision board',`<p>Use A as the landing page, then borrow B’s pay map and C’s comparison when the student wants more detail.</p><div class="idea-grid">${[['Two clocks, not one','Five years after qualification and five years from today answer different questions. Include time in school and paid training in the second view.'],['Three education lanes','Keep bachelor/graduate, associate/certificate, and apprenticeship/work routes distinct. Do not hide good options in a false college/no-college binary.'],['A budget gap is not a career rejection','Say “below your target,” keep the interest match, and offer choices about cost, hours or the route.'],['A small next experiment','End with a job shadow, a short activity, or a useful conversation. A student should leave with one next step, not a forced career commitment.'],['Unknown is a valid result','A simple “not enough evidence yet” screen is better than unrelated recommendations. Offer one focused question or a low-pressure activity.'],['Location and working hours','Use the student’s chosen location, expected hours and reliable local pay evidence. Do not treat annualized pay as a guarantee of full-time work.'],['Match confidence and salary confidence','Keep “supported match” separate from “pay estimated.” Explain why a recommendation is shown and whether wages or timing remain uncertain.']].map(([title,text])=>`<article class="idea-item"><b>${title}</b><p>${text}</p></article>`).join('')}</div>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||!data)return;const a=b.dataset.action,id=b.dataset.id;if(a==='continue-profile'){parent.postMessage({type:'fieldguide-board-navigate',route:'journey/interest/'+profile.resumeInterestIndex},location.origin);return;}if(a==='all-fields'){parent.postMessage({type:'fieldguide-board-navigate',route:'plan'},location.origin);return;}if(a==='clarify-career'){if(data.modelView)return;parent.postMessage({type:'fieldguide-board-navigate',route:'journey/clarify/'+id+'/0'},location.origin);return;}if(a==='match-reason'){const o=find(id);if(o)showDialog(o.title,reason086(o));return;}if(a==='close'){dialog.close();return;}if(a==='concept'){state.concept=b.dataset.value;render();document.querySelector('[data-action="concept"][data-value="'+state.concept+'"]')?.focus({preventScroll:true});return;}if(a==='career'){careerDetail(id);return;}if(a==='ideas'){ideas();return;}if(a==='field'){state.field=b.dataset.value;render();document.querySelector('[data-action="field"][data-value="'+state.field+'"]')?.focus({preventScroll:true});return;}if(a==='stage'){state.stage=b.dataset.value;render();document.querySelector('[data-action="stage"][data-value="'+state.stage+'"]')?.focus({preventScroll:true});return;}if(a==='all-chart'){state.allChart=!state.allChart;render();return;}if(a==='jump-compare'){document.getElementById('compare')?.scrollIntoView({behavior:'smooth',block:'center'});return;}if(a==='more-options'){state.exploreLimit+=12;render();return;}if(a==='reset'){Object.assign(state,{query:'',route:'all',minimum:'',coversOnly:false,topOnly:false,includeCandidates:true,field:'all'});render();return;}if(a==='save'){saved.has(id)?saved.delete(id):saved.add(id);parent.postMessage({type:'fieldguide-board-save',id,saved:saved.has(id)},location.origin);if(dialog.open)dialog.close();render();notify(saved.has(id)?'Saved.':'Removed from saved.');return;}
if(a==='saved'){showDialog('Your saved options',`<p>Your saved careers.</p>${saved.size?[...saved].map(id=>find(id)).filter(Boolean).map(o=>`<div class="career-row"><button class="role-name" data-action="career" data-id="${h(o.id)}">${h(o.title)}</button><span class="row-pay">${money(o.entry)}</span><button class="save" data-action="save" data-id="${h(o.id)}" aria-label="Unsave ${h(o.title)}">★</button></div>`).join(''):'<div class="empty"><p>Use the star beside a career to keep it here.</p></div>'}`);return;}
if(a==='open-career'){if(data.modelView){notify('Model preview: your own plan stays unchanged.');return;}parent.postMessage({type:'fieldguide-board-navigate',route:'journey/profession/'+id},location.origin);return;}if(a==='lifestyle'){parent.postMessage({type:'fieldguide-board-navigate',route:'journey/lifestyle'},location.origin);return;}if(a==='apply-target'){state.target=Number(document.getElementById('target-slider').value);dialog.close();render();return;}if(a==='restore-target'){state.target=profile.lifestyle.target;dialog.close();render();return;}
if(a==='timeline'){showDialog('Two different five-year comparisons',`<h3>Five years after qualification</h3><p>The figures on this board use the existing career planning model. The clock starts after required study, credentials and preparation. These are scenarios, not promises of raises.</p><h3>Five years from today</h3><p>This needs a study timeline, any paid apprenticeship or residency, tuition and aid, living costs while studying, and loan payments. A student in a long program may still be studying at that point.</p><p>Five-year-from-today earnings need a separate study and funding timeline. </p>`);return;}
if(a==='method'){showDialog('What the pay comparison means',`<p>These results use the answers saved in the selected plan. Model views are fictional and stay separate from your account.</p><h3>Interest fit and budget fit are separate</h3><p>Only specifically supported careers receive a Top or supported label. A lower salary does not erase an interest fit. Unconfirmed possibilities keep their own label.</p><h3>Pay is an estimate</h3><p>Amounts are annual gross income from the existing Fieldguide wage and planning models. Five-year values are planning scenarios or employer examples, not salaries measured at exactly five years. Missing five-year figures stay unestimated.</p><h3>Your target</h3><p>The income target comes from the selected plan’s lifestyle-budget assumptions. The green zone means the estimate clears that target; it is not an offer or a guarantee. All loan payments not already entered need separate planning.</p><p>Every career detail includes its wage sources, geography, training stage and assumptions.</p>`);return;}
if(a==='experience'){if(data.modelView){showDialog('Explore this career','<p>Read the work, preparation and pay sources in these career details. Model interests remain unchanged.</p>');return;}parent.postMessage({type:'fieldguide-board-navigate',route:'journey/profession/'+id},location.origin);return;}if(a==='possibilities'){state.includeCandidates=true;render();document.getElementById('explore')?.scrollIntoView();return;}
if(a==='next-question'){if(data.modelView){showDialog('Interests still to explore','<p>This model has unresolved interests. Its unknown answers remain unknown; no new answers are added from this board.</p>');return;}parent.postMessage({type:'fieldguide-board-navigate',route:profile.candidates[0]?'journey/clarify/'+profile.candidates[0].id+'/0':'journey/profile'},location.origin);return;}
});
document.addEventListener('input',e=>{if(e.target.id==='career-search'){state.query=e.target.value;renderPreservingFocus('career-search');}if(e.target.id==='target-slider')document.getElementById('target-value').textContent=money(Number(e.target.value))+' / year';});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='demo-profile'){setProfile(t.value);render();document.getElementById('demo-profile')?.focus({preventScroll:true});return;}const props={'route-filter':'route','sort-filter':'sort','budget-only':'coversOnly','top-only':'topOnly','minimum-pay':'minimum','include-possibilities':'includeCandidates'};if(props[t.id]){state[props[t.id]]=t.type==='checkbox'?t.checked:t.value;render();document.getElementById(t.id)?.focus({preventScroll:true});return;}if(t.dataset.pairSlot!==undefined){const i=Number(t.dataset.pairSlot);if(state.pair[1-i]===t.value){notify('Choose a different career for the other side.');render();return;}state.pair[i]=t.value;render();return;}if(t.dataset.compare){const id=t.dataset.compare;if(t.checked){state.pair[collegeLane(find(id))?0:1]=id;}else state.pair=state.pair.map(x=>x===id?null:x);render();}});

function comparisonOffers085(){return [...new Map([...profile.supported,...profile.candidates].map(o=>[o.id,o])).values()];}
function matchLabel085(o){return o.candidate?(o.mixedInterests?'Mixed':'Explore'):o.top?'Top':'Supported';}
function tableFit085(o){const fit=status(o);return fit.key==='unknown'?(o.requiresExperience?'Experience first':'Estimate pending'):fit.key==='gap'?money(Math.max(0,state.target-income(o)))+' short':fit.key==='good'?'Above target':'Meets target';}
function score086(o){return !Number.isFinite(o.correlation)?'Not scored':o.correlation>=.729?'Best interest fit':o.correlation>=.608?'Good interest fit':o.correlation>=0?'Some overlap':'Explore further';}
function reason086(o){const c=o.confirmation;return `<h3>${score086(o)}</h3><p>Similarity between your broad interests and this career. It is not a probability or a measure of ability.</p><h3>${o.candidate?'Why confirmation is needed':o.top?'Why this is Top':'Why this is supported'}</h3><p>${o.candidate?'A broad interest or selected activity connects you to this career. Profession-specific evidence is still incomplete or conflicting.':o.top?'This career meets the profession-specific evidence checks and is among your first three supported recommendations.':'This career meets the profession-specific evidence checks, outside your first three recommendations.'}</p>${c?`<p>${h(c.requirement||'Direct profession-specific evidence is required.')}</p><p>${c.asked} questions reached · ${c.taskContexts} supported task contexts · ${c.specificInterests} supported defining interests</p>${o.knownEvidence.length?`<h3>Recorded supporting evidence</h3><ul>${o.knownEvidence.map(x=>`<li>${h(x)}</li>`).join('')}</ul>`:''}${c.contrary.length?`<h3>Conflicting answers</h3><ul>${c.contrary.map(x=>`<li>${h(x)}</li>`).join('')}</ul>`:''}${c.missing.length?`<h3>Still to confirm</h3><ul>${c.missing.map(x=>`<li>${h(x)}</li>`).join('')}</ul><p>Unanswered or uncertain interests remain unknown.</p>`:''}`:'<p>This saved model records the match status, but detailed check counts are not included in this view.</p>'}<p>A stronger interest fit alone does not earn a Top label.</p>${data.modelView?`<a href="./developer/noncollege-087.html?model=${encodeURIComponent(profile.id)}" target="_top">Recorded model checks →</a>`:`<button class="secondary-button" data-action="clarify-career" data-id="${h(o.id)}">Check these interests →</button>`}`;}
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent)return;if(e.data?.type==='fieldguide-board-viewport'){const m=e.data;if(Number.isFinite(m.top)&&Number.isFinite(m.height)){dialog.style.top=Math.max(0,m.top)+'px';dialog.style.maxHeight=Math.max(250,m.height)+'px';dialog.style.margin='0 auto';}return;}if(e.data?.type!=='fieldguide-board-init')return;if(dialog.open)dialog.close();data=e.data.data;data.modelView=!!e.data.preview;state={concept:'a',stage:'entry',sort:'match'};setProfile(data.profiles[0].id);render();});
new ResizeObserver(()=>parent.postMessage({type:'fieldguide-board-height',height:Math.ceil(document.body.getBoundingClientRect().height)},location.origin)).observe(document.body);
parent.postMessage({type:'fieldguide-board-ready'},location.origin);
